class String(Field[str]):
    """A string field.

    :param strip_whitespace: Remove leading and trailing whitespace when loading.
        Defaults to False. Serialization is unchanged.
    :param kwargs: The same keyword arguments that :class:`Field` receives.
    """

    #: Default error messages.
    default_error_messages = {
        "invalid": "Not a valid string.",
        "invalid_utf8": "Not a valid utf-8 string.",
    }

    def __init__(self, *, strip_whitespace: bool = False, **kwargs):
        super().__init__(**kwargs)
        self.strip_whitespace = strip_whitespace

    def _serialize(self, value, attr, obj, **kwargs) -> str | None:
        if value is None:
            return None
        return utils.ensure_text_type(value)

    def _deserialize(self, value, attr, data, **kwargs) -> str:
        if not isinstance(value, (str, bytes)):
            raise self.make_error("invalid")
        try:
            text = utils.ensure_text_type(value)
            return text.strip() if self.strip_whitespace else text
        except UnicodeDecodeError as error:
            raise self.make_error("invalid_utf8") from error
